mapper.select:
SELECT COUNT(*)
  FROM TB_MBR
 WHERE HP_NO = #{HP_NO}
   AND MBR_STAT <> 'W'

   AND MBR_ID <> #{MBR_ID}

mapper.insert:
INSERT INTO TB_MBR_GRADE_HIST (MBR_ID, HIST_SEQ, BF_GRADE_CD, AF_GRADE_CD, CHG_TYPE, CNFM_AMT_6M, CHG_RSN, CHG_DT, CHG_ID)
SELECT #{MBR_ID}, NVL(MAX(HIST_SEQ), 0) + 1, #{BF_GRADE_CD}, #{AF_GRADE_CD}, #{CHG_TYPE}, #{CNFM_AMT_6M},
       #{CHG_RSN}, SYSDATE, #{CHG_ID}
  FROM TB_MBR_GRADE_HIST
 WHERE MBR_ID = #{MBR_ID}
